sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.searchText = "";
  c.selectedRental = "";
  c.submitting = false;
  c.message = "";
  c.messageType = "success";
  c.initial = ((c.data.studentName || "S").charAt(0)).toUpperCase();

  c.filteredRentals = function() {
    var term = (c.searchText || "").toLowerCase().trim();

    return (c.data.rentals || []).filter(function(rental) {
      return !term ||
        (rental.assetName || "").toLowerCase().indexOf(term) > -1 ||
        (rental.number || "").toLowerCase().indexOf(term) > -1 ||
        (rental.type || "").toLowerCase().indexOf(term) > -1;
    });
  };

  c.selectRental = function(id) {
    c.selectedRental = c.selectedRental === id ? "" : id;
    c.message = "";
  };

  c.returnItem = function() {
    if (!c.selectedRental || c.submitting) return;

    c.submitting = true;
    c.message = "";

    c.server.get({
      action: "returnItem",
      rentalId: c.selectedRental
    }).then(function(response) {
      var result = response.data || {};

      // Refresh the displayed list from the server after the update.
      c.data.rentals = result.rentals || [];
      c.data.studentName = result.studentName || c.data.studentName;
      c.initial = ((c.data.studentName || "S").charAt(0)).toUpperCase();

      if (result.success) {
        c.message = result.message || "The return has been recorded.";
        c.messageType = "success";
        c.selectedRental = "";
      } else {
        c.message = result.message || "The return could not be recorded.";
        c.messageType = "error";
      }
    }, function() {
      c.message = "A server error occurred. Please try again.";
      c.messageType = "error";
    }).finally(function() {
      c.submitting = false;
    });
  };
};

sp_widget.css:
.co-return-page {
  --purple: #8062c7;
  --purple-dark: #39285f;
  --border: #e6dcf7;
  --muted: #81749b;
  font-family: inherit;
  color: var(--purple-dark);
  background: #f3f8f9;
  min-height: 100vh;
  padding: 14px 16px;
  box-sizing: border-box;
}

.co-return-page *,
.co-return-page *::before,
.co-return-page *::after {
  box-sizing: border-box;
}

.co-return-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 24px;
  max-width: 1440px;
  margin: 0 auto;
  align-items: stretch;
}

.co-return-sidebar {
  display: flex;
  flex-direction: column;
  min-height: calc(100vh - 28px);
  padding: 18px 10px 14px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: linear-gradient(180deg, #f8f4ff, #f2edfc);
}

.co-return-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 5px 28px;
  color: var(--purple-dark);
  text-decoration: none;
}

.co-return-logo {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  background: var(--purple);
  color: white;
  font-size: 17px;
  font-weight: 700;
}

.co-return-brand strong,
.co-return-brand small,
.co-return-user strong,
.co-return-user small {
  display: block;
}

.co-return-brand strong { font-size: 13px; }
.co-return-brand small,
.co-return-user small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
}

.co-return-nav-label {
  margin: 0 8px 10px;
  color: #9485b2;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
}

.co-return-nav {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  margin-bottom: 3px;
  padding: 10px;
  border-radius: 9px;
  color: #5d4a80;
  font-size: 12px;
  text-decoration: none;
}

.co-return-nav > span {
  width: 15px;
  color: var(--purple);
  text-align: center;
  font-size: 14px;
}

.co-return-nav:hover,
.co-return-active {
  background: #e8defb;
  color: #4c347e;
}

.co-return-account-label { margin-top: 25px; }

.co-return-user {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: auto;
  padding: 14px 5px 0;
  border-top: 1px solid #e2d8f2;
}

.co-return-avatar {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #e7dcfb;
  color: #6547a5;
  font-size: 12px;
  font-weight: 700;
}

.co-return-user strong {
  font-size: 11px;
  overflow-wrap: anywhere;
}

.co-return-main {
  min-width: 0;
  padding-top: 5px;
}

.co-return-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 22px;
}

.co-return-eyebrow {
  margin-bottom: 8px;
  color: var(--purple);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.co-return-header h1 {
  margin: 0 0 7px;
  color: #30224e;
  font-size: clamp(26px, 2.4vw, 32px);
  line-height: 1.2;
}

.co-return-header p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.co-return-outline {
  flex-shrink: 0;
  padding: 10px 13px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: white;
  color: #6547a5;
  font-size: 11px;
  text-decoration: none;
}

.co-return-intro {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 16px;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 13px;
  background: white;
}

.co-return-intro-icon,
.co-return-asset-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 11px;
  background: #f0e8ff;
  color: var(--purple);
  font-size: 21px;
}

.co-return-intro h2 {
  margin: 0 0 6px;
  font-size: 16px;
}

.co-return-intro p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.co-return-notice {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding: 12px 15px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #f7f3ff;
  color: #543b82;
  font-size: 12px;
  line-height: 1.5;
}

.co-return-notice.success {
  border-color: #c8e8d5;
  background: #f0faf4;
  color: #246a47;
}

.co-return-notice.error {
  border-color: #f0c8d0;
  background: #fff3f5;
  color: #a12e48;
}

.co-return-notice button {
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 19px;
  cursor: pointer;
}

.co-return-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: 25px;
  padding: 16px 5px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: white;
}

.co-return-summary > div {
  padding: 0 18px;
  border-right: 1px solid #eee6f8;
}

.co-return-summary > div:last-child { border-right: 0; }

.co-return-summary span,
.co-return-summary strong { display: block; }

.co-return-summary span {
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 11px;
}

.co-return-summary strong {
  font-size: 23px;
}

.co-return-content { margin-bottom: 22px; }

.co-return-section-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 13px;
}

.co-return-section-heading h2 {
  margin: 0 0 5px;
  font-size: 19px;
}

.co-return-section-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.co-return-count {
  padding: 6px 9px;
  border-radius: 7px;
  background: #eee7fa;
  color: #6947a7;
  font-size: 10px;
  white-space: nowrap;
}

.co-return-search {
  display: flex;
  align-items: center;
  gap: 11px;
  height: 44px;
  margin-bottom: 14px;
  padding: 0 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: white;
}

.co-return-search > span {
  color: var(--purple);
  font-size: 17px;
}

.co-return-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #382b54;
  font-family: inherit;
  font-size: 12px;
}

.co-return-search button {
  border: 0;
  background: transparent;
  color: #6947a7;
  font-size: 11px;
  cursor: pointer;
}

.co-return-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.co-return-card {
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 13px;
  background: white;
  transition: border-color .15s ease, box-shadow .15s ease;
}

.co-return-card:hover,
.co-return-card.chosen {
  border-color: #b9a3e6;
  box-shadow: 0 4px 13px rgba(70, 48, 105, .05);
}

.co-return-card.chosen { background: #fcfaff; }

.co-return-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-bottom: 13px;
}

.co-return-asset-icon {
  width: 36px;
  height: 36px;
  font-size: 17px;
}

.co-return-status {
  padding: 6px 9px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.co-return-status.active { background: #e9f7ef; color: #26784e; }
.co-return-status.due { background: #fff3df; color: #a76513; }
.co-return-status.overdue { background: #fdebef; color: #b23a53; }

.co-return-type {
  margin-bottom: 5px;
  color: #8b7ba7;
  font-size: 10px;
  letter-spacing: .4px;
}

.co-return-card h3 {
  margin: 0 0 5px;
  color: #35234f;
  font-size: 15px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.co-return-number {
  margin: 0 0 13px;
  color: var(--muted);
  font-size: 11px;
}

.co-return-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 13px 0;
  margin-bottom: 13px;
  border-top: 1px solid #eee7f8;
  border-bottom: 1px solid #eee7f8;
}

.co-return-details span,
.co-return-details strong { display: block; overflow-wrap: anywhere; }

.co-return-details span {
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 10px;
}

.co-return-details strong {
  color: #44315f;
  font-size: 11px;
}

.co-return-select {
  width: 100%;
  min-height: 40px;
  padding: 10px 12px;
  border: 1px solid #d8c9f1;
  border-radius: 8px;
  background: white;
  color: #6947a7;
  font-family: inherit;
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
}

.co-return-card.chosen .co-return-select {
  border-color: var(--purple);
  background: #8062c7;
  color: white;
}

.co-return-select:disabled { opacity: .6; cursor: not-allowed; }

.co-return-empty {
  padding: 32px 18px;
  border: 1px dashed #d8c9f1;
  border-radius: 13px;
  background: white;
  text-align: center;
}

.co-return-empty-icon {
  margin-bottom: 10px;
  color: #39845b;
  font-size: 28px;
}

.co-return-empty strong { font-size: 15px; }

.co-return-empty p {
  margin: 8px 0 12px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.co-return-empty a {
  color: #6d4db4;
  font-size: 12px;
  font-weight: 650;
  text-decoration: none;
}

.co-return-confirm {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 20px;
  padding: 18px;
  border: 1px solid #d8c9f1;
  border-radius: 12px;
  background: #faf7ff;
}

.co-return-confirm h2 {
  margin: 0 0 6px;
  font-size: 16px;
}

.co-return-confirm p {
  max-width: 520px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.co-return-confirm-actions {
  display: flex;
  flex-shrink: 0;
  gap: 9px;
}

.co-return-confirm-actions button {
  min-height: 40px;
  padding: 10px 13px;
  border-radius: 8px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 650;
  cursor: pointer;
}

.co-return-cancel {
  border: 1px solid var(--border);
  background: white;
  color: #604687;
}

.co-return-submit {
  border: 0;
  background: var(--purple);
  color: white;
}

.co-return-submit:hover:not(:disabled) { background: #6d4db4; }
.co-return-confirm-actions button:disabled { opacity: .6; cursor: not-allowed; }

.co-return-help {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 20px;
  padding: 16px 18px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: #faf7ff;
}

.co-return-help strong { font-size: 13px; }

.co-return-help p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.co-return-help a,
.co-return-footer a {
  color: #6d4db4;
  font-size: 11px;
  text-decoration: none;
}

.co-return-footer {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 15px 2px;
  border-top: 1px solid #e5dcef;
  color: var(--muted);
  font-size: 10px;
}

.co-return-footer strong { color: #45345f; }
.co-return-footer > span:last-child { display: flex; gap: 16px; }

@media (max-width: 900px) {
  .co-return-layout {
    grid-template-columns: 190px minmax(0, 1fr);
    gap: 16px;
  }

  .co-return-list { grid-template-columns: 1fr; }

  .co-return-confirm {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 650px) {
  .co-return-page { padding: 10px; }
  .co-return-layout { grid-template-columns: 1fr; }
  .co-return-sidebar { min-height: auto; }
  .co-return-user { margin-top: 16px; }
  .co-return-header { flex-direction: column; }
  .co-return-help { align-items: flex-start; flex-direction: column; }
  .co-return-confirm-actions { width: 100%; flex-wrap: wrap; }
}

sp_widget.script:
(function() {
  var userId = gs.getUserID();
  var nowMs = new GlideDateTime().getNumericValue();
  var DAY_MS = 86400000;

  data.studentName = gs.getUserDisplayName() || "Campus member";
  data.rentals = [];
  data.success = false;
  data.message = "";

  function formatDate(value) {
    if (!value) return "";
    try {
      return new GlideDateTime(value).getLocalDate().getByFormat("dd MMM yyyy");
    } catch (e) {
      return "";
    }
  }

  if (input && input.action === "returnItem") {
    var rentalId = (input.rentalId || "").toString();
    var record = new GlideRecord("u_student_rental");

    if (!rentalId ||
        !record.get(rentalId) ||
        record.getValue("u_student") !== userId ||
        (record.getValue("u_status") || "").toLowerCase() !== "active") {
      data.success = false;
      data.message = "This active rental could not be found for your account. Refresh the page and try again.";
    } else {
      record.setValue("u_status", "returned");
      record.setValue("u_return_date", new GlideDateTime());

      var updatedId = record.update();

      if (updatedId) {
        data.success = true;
        data.message = "Return recorded successfully. Your rental has been marked as returned.";
      } else {
        data.success = false;
        data.message = "The return could not be saved. Please try again or contact the campus desk.";
      }
    }
  }

  // Always return the latest active rentals for this signed-in student.
  var rental = new GlideRecord("u_student_rental");
  rental.addQuery("u_student", userId);
  rental.addQuery("u_status", "active");
  rental.orderBy("u_due_date");
  rental.query();

  while (rental.next()) {
    var dueValue = rental.getValue("u_due_date");
    var dueMs = dueValue
      ? new GlideDateTime(dueValue).getNumericValue()
      : null;

    var isOverdue = dueMs !== null && dueMs < nowMs;
    var daysLeft = dueMs === null
      ? null
      : Math.ceil((dueMs - nowMs) / DAY_MS);

    var isDueSoon = !isOverdue &&
      daysLeft !== null &&
      daysLeft >= 0 &&
      daysLeft <= 2;

    var assetType = "";
    var asset = rental.u_asset.getRefRecord();

    if (asset && asset.isValidRecord()) {
      assetType = asset.getDisplayValue("u_asset_type") || "";
    }

    data.rentals.push({
      id: rental.getUniqueValue(),
      number: rental.getDisplayValue("u_number"),
      assetName: rental.getDisplayValue("u_asset") || "Campus resource",
      type: assetType,
      rentalDate: formatDate(rental.getValue("u_rental_date")),
      dueDate: formatDate(dueValue),
      isOverdue: isOverdue,
      isDueSoon: isDueSoon
    });
  }
})();
